1230	// chunk → true partial; writes the full 64×N tile (LOCAL rows) to the slot.
1231	template <int N>
1232	__device__ __forceinline__ void vittc_dw_run_tile_splitk(
1233	        const VitDwSpec spec[10], int gt, int kc, int G,
1234	        const __nv_bfloat16* __restrict__ dh0,
1235	        float* __restrict__ dw_part, __nv_bfloat16* sA, __nv_bfloat16* sB) {
1236	    int s, m_atom, n_tile;
1237	    vittc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1238	    const VitDwSpec& sp = spec[s];
1239	    const int mbase = m_atom * 64;
1240	    const int n0 = n_tile * N;
1241	    const int Nout = sp.Nout, Kin = sp.Kin;
1242	    // KS = total k-atoms. kind==1 (patch_proj): K=Tp patch rows padded UP to /16.
1243	    // kind==0: K=T or K=B (already multiples of 16).
1244	    const int KS = (sp.kind == 1)
1245	        ? (((sp.K + wgs::kWgmmaAtomK - 1) / wgs::kWgmmaAtomK))   // ceil(Tp/16)
1246	        : (sp.K / wgs::kWgmmaAtomK);
1247	    const int k0 = (int)(((int64_t)kc       * KS) / G);          // floor-balanced
1248	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1249	    const int kc_steps = k1 - k0;
1250	    float* slot = dw_part + ((int64_t)gt * G + kc) * kVitDwTileFloats;
1251	    // Empty-chunk guard (KS<G): a k_steps=0 GEMM would emit the uninitialized
1252	    // accumulator → zero the slot + return (the reduce sums all G slots).
1253	    if (kc_steps <= 0) {
1254	        for (int i = threadIdx.x; i < 64 * N; i += blockDim.x) slot[i] = 0.0f;
1255	        __syncthreads();
1256	        return;
1257	    }
1258	    auto out = [&] (int m, int n, float v) {
1259	        const int lr = m - mbase;
1260	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1261	    if (sp.kind == 1) {
1262	        // patch_proj: A[m=out,k=patchrow]=dh0[token row of patchrow, out] (transposed);
1263	        // B[n=in,k=patchrow]=X_patch[patchrow,in]. The k index here is the LOCAL chunk
1264	        // atom-step; the global patch row is (k0*16 + k). Pad rows (>=Tp) → 0.
1265	        const int Tp = sp.K;
1266	        const __nv_bfloat16* X = sp.X;
1267	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1268	            const int gk = k0 * wgs::kWgmmaAtomK + k;
1269	            if (m >= Nout || gk >= Tp) return __float2bfloat16(0.f);
1270	            const int si = gk / vit::kNPatch, p = gk % vit::kNPatch;
1271	            const int trow = si * vit::kSeq + (1 + p);
1272	            return dh0[(int64_t)trow * vit::kD + m]; };
1273	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1274	            const int gk = k0 * wgs::kWgmmaAtomK + k;
1275	            int nn = n0 + n; if (nn >= Kin || gk >= Tp) return __float2bfloat16(0.f);
1276	            return X[(int64_t)gk * Kin + nn]; };
1277	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1278	            mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1279	        return;
1280	    }
1281	    // kind==0: A[m=out,k=t]=dY[t,out]; B[n=in,k=t]=X[t,in] (both transposed reads).
1282	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1283	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1284	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1285	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1286	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1287	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1288	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1289	}
