1292	// ascending-kc → grad. SAME (gt → geometry) decode as the partial.
1293	template <int N>
1294	__device__ __forceinline__ void vittc_dw_reduce_splitk(
1295	        const VitDwSpec spec[10], int n_dw, int G, const float* __restrict__ dw_part,
1296	        float* __restrict__ grad, int cta, int nCTA) {
1297	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1298	        int s, m_atom, n_tile;
1299	        vittc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1300	        const VitDwSpec& sp = spec[s];
1301	        const int mbase = m_atom * 64;
1302	        const int n0 = n_tile * N;
1303	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1304	        const int Nrow = (sp.Nout - mbase) < 64 ? (sp.Nout - mbase) : 64;
1305	        const int64_t base = (int64_t)gt * G * kVitDwTileFloats;
1306	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1307	            const int row = idx / n_real, col = idx % n_real;
1308	            float accv = 0.0f;
1309	            for (int kc = 0; kc < G; ++kc)
1310	                accv += dw_part[base + (int64_t)kc * kVitDwTileFloats + (int64_t)row * N + col];
1311	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1312	        }
1313	    }
1314	}
