1151	__device__ __forceinline__ void mbtc_dw_run_tile_splitk(
1152	        const MbDwSpec spec[8], int gt, int kc, int G, float* __restrict__ dw_part,
1153	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1154	    int s, m_atom, n_tile;
1155	    mbtc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1156	    const MbDwSpec& sp = spec[s];
1157	    const int mbase = m_atom * 64;
1158	    const int n0 = n_tile * N;
1159	    const int kc_steps = (sp.T / wgs::kWgmmaAtomK) / G;   // equal chunks (G | k_steps_total)
1160	    const int k0 = kc * kc_steps;
1161	    const int Nout = sp.Nout, Kin = sp.Kin;
1162	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1163	    // srcA/srcB offset the K axis by k0*16 (the chunk's first token); k local to chunk.
1164	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1165	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1166	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1167	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1168	    float* slot = dw_part + ((int64_t)gt * G + kc) * kMbDwTileFloats;
1169	    // The GEMM calls out(mbase+row, col, v) with GLOBAL m = mbase+row (srcA reads
1170	    // dY[m·Nout] so m MUST stay global), but the slot holds only THIS atom's 64
1171	    // LOCAL rows → index by (m - mbase). A `m < 64` guard would NEVER fire for
1172	    // m_atom>=1 (mbase>=64) → that atom's slot stays UNWRITTEN and the reduce sums
1173	    // garbage (the rel~1.0 dW bug). Local-row indexing fills every slot fully.
1174	    auto out  = [&] (int m, int n, float v) {
1175	        const int lr = m - mbase;
1176	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1177	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1178	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1179	}
