1188	        int s, m_atom, n_tile;
1189	        mbtc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1190	        const MbDwSpec& sp = spec[s];
1191	        const int mbase = m_atom * 64;
1192	        const int n0 = n_tile * N;
1193	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1194	        const int Nrow = (sp.Nout - mbase) < 64 ? (sp.Nout - mbase) : 64;
1195	        const int64_t base = (int64_t)gt * G * kMbDwTileFloats;
1196	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1197	            const int row = idx / n_real, col = idx % n_real;
1198	            float accv = 0.0f;
1199	            for (int kc = 0; kc < G; ++kc)            // ascending chunk → deterministic
1200	                accv += dw_part[base + (int64_t)kc * kMbDwTileFloats + (int64_t)row * N + col];
1201	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
