1206	// dt_proj.bias db = Σ_T ddt_pre (the ONLY GEMM bias). The reduction over T is
1207	// O(T=B·kSeq) PER output element; striping it across ALL nCTA CTAs (not letting
1208	// every CTA redundantly recompute the full O(T) sum for every output and race-write
1209	// the same grad slot — the measured ~19%-of-wall uniform straggler: mean≈max across
1210	// CTAs because ALL 132 did the SAME full work) cuts that ~nCTA-fold. We enumerate a
1211	// GLOBAL bias-output index over the (bias-carrying spec s, output o) space and
1212	// round-robin it by (cta·blockDim + tid) so each output is summed by exactly ONE
1213	// thread on ONE CTA — single owner, deterministic, no race, no redundancy.
1214	__device__ __forceinline__ void mbtc_dw_biases(
1215	        const MbDwSpec spec[8], float* __restrict__ grad, int cta, int nCTA) {
1216	    int total_bias = 0;
1217	    #pragma unroll
1218	    for (int s = 0; s < 8; ++s) total_bias += spec[s].has_bias ? spec[s].Nout : 0;
1219	    const int64_t base_thread = (int64_t)cta * blockDim.x + threadIdx.x;
1220	    const int64_t stride = (int64_t)nCTA * blockDim.x;
1221	    for (int64_t gi = base_thread; gi < total_bias; gi += stride) {
1222	        int s = 0, o = (int)gi;
1223	        #pragma unroll
1224	        for (int ss = 0; ss < 8; ++ss) {
1225	            if (!spec[ss].has_bias) continue;
1226	            if (o < spec[ss].Nout) { s = ss; break; }
1227	            o -= spec[ss].Nout;
1228	        }
