870	// (occ·n_sms with occupancy-fill, or the cap). The caller MUST size the workspace
871	// with this — the per-CTA scratch/partials are nCTA·slab, so sizing for n_sms while
872	// the launcher runs occ·n_sms would overflow. Returns 0 on a CUDA-attr failure (the
873	// caller should treat that as "fall back to a conservative larger size").
874	template <OptId Opt>
875	int mb_tc_launched_nctas(int dev, int ncta_cap) {
876	    int n_sms = 0;
877	    if (cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev) != cudaSuccess) return 0;
878	    int occ = 0;
879	    if (cudaOccupancyMaxActiveBlocksPerMultiprocessor(
880	            &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK, 0) != cudaSuccess)
881	        return 0;
882	    if (occ < 1) return 0;
883	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
884	    unsigned launch_ctas = (unsigned)n_sms * waves;
885	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
886	    return (int)launch_ctas;
887	}
