889	template <OptId Opt>
890	cudaError_t launch_fused_mamba_megakernel_tc(
891	        PersistentContext ctx, float* params, MambaTokenCtx tok,
892	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
893	        int ncta_cap = 0) {
894	    int dev = 0;
895	    cudaError_t err = cudaGetDevice(&dev);
896	    if (err != cudaSuccess) return err;
897	    int n_sms = 0;
898	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
899	    if (err != cudaSuccess) return err;
900	
901	    int occ = 0;
902	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
903	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK,
904	        /*dynamicSMemBytes=*/0);
905	    if (err != cudaSuccess) return err;
906	    if (occ < 1) return cudaErrorLaunchOutOfResources;
907	
908	    // OCCUPANCY-FILL: at min-blocks≥2 the kernel is built ≤128 reg/thread so `occ`
909	    // CTAs co-reside per SM. Launch occ·n_sms CTAs (one full residency set) so the
910	    // co-resident CTAs hide each other's HBM latency across the scan/conv/LN phases
911	    // that run fully exposed at occ=1 — the persistent grid barrier rendezvous is
912	    // over the LAUNCHED count and occ·n_sms are guaranteed simultaneously resident,
913	    // so it stays hang-free. Determinism is per fixed launched nCTA (ascending-CTA
914	    // reduce). At min-blocks==1 (shipped default) occ==1 → identical to before.
915	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
916	    unsigned launch_ctas = (unsigned)n_sms * waves;
917	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
918	    ctx.n_ctas = launch_ctas;
919	    // B%16: the dW K-loop contracts K=T=B·8 in 16-step atoms. It ALSO guarantees
920	    // FULL tiles (T%kTileM==0 for kTileM∈{64,128}), which the projection GEMMs
921	    // REQUIRE — they process a compile-time M-extent of kTileM rows (kAtomsM
922	    // atoms), NOT the runtime `nrows`; a partial final tile would feed garbage
923	    // pad rows to the wgmma while the scalar scan/conv loops process only nsamp.
924	    // (A future relaxation to B%2 would satisfy the K-atom reason but silently
925	    // break partial tiles — keep B%16.)
926	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
927	    // SPLIT-K dW (G>1) needs equal 16-aligned K-chunks: G must divide k_steps_total
928	    // = T/16 = B·kSeq/16 = B/2 (kSeq=8). With B%16==0, B/2%4==0, so G∈{1,2,4} are
929	    // always legal; a larger/odd G that doesn't divide B/2 would silently DROP the
930	    // remainder k-steps from every dW (a correctness bug) — REFUSE loudly instead.
931	    if (mbtc::kMbDwSplitK > 1 && (((int64_t)tok.B * mb::kSeq / wgs::kWgmmaAtomK) % mbtc::kMbDwSplitK) != 0)
932	        return cudaErrorInvalidValue;
933	
934	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
935	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
936	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
